(()=>{
const $=id=>document.getElementById(id),L=LayoutLab;let selected=0,layout=null,state=null,stationId=null,clock=null,plc=LayoutPLC.fresh(),passed=false;
const titles={belt:'Conveyor',sensor:'Inspection photoeye',stop:'Timed stop',lift:'Lift cycle',exit:'Discharge',sort:'Route diverter',merge:'Merge zone'};
let completed=[];try{completed=JSON.parse(localStorage.getItem('plcquest.layouts.plc.done.v1')||'[]');if(!Array.isArray(completed))completed=[];}catch{}
function edges(l){const result=new Map();for(const r of l.routes)for(let i=1;i<r.length;i++)result.set(r[i-1]+':'+r[i],[r[i-1],r[i]]);return [...result.values()];}
function diagram(l,s,mini=false){const nodes=Object.fromEntries(l.nodes.map(n=>[n.id,n]));let out='';
 for(const [a,b]of edges(l)){const x=nodes[a],y=nodes[b],dx=y.x-x.x,dy=y.y-x.y,len=Math.hypot(dx,dy),ux=dx/len,uy=dy/len;const ax=x.x+ux*42,ay=x.y+uy*32,bx=y.x-ux*44,by=y.y-uy*34;
 out+=`<path d="M${ax} ${ay}L${bx} ${by}" stroke="#65745b" stroke-width="19" fill="none"/><path d="M${ax} ${ay}L${bx} ${by}" stroke="#bac6a0" stroke-width="1.5" stroke-dasharray="5 10"/><path d="M-7,-5L2,0L-7,5" transform="translate(${(ax+bx)/2},${(ay+by)/2}) rotate(${Math.atan2(dy,dx)*180/Math.PI})" fill="none" stroke="#e2b77c" stroke-width="3"/>`;}
 for(const n of l.nodes){const st=s?.stations[n.id],active=st?.output,b=st?.box,fill=st?.fault?'#a64939':active?'#69815d':'#404d40';
 out+=`<g ${mini?'':`data-id="${n.id}" role="button" tabindex="0" aria-label="${n.id} ${titles[n.type]}"`} transform="translate(${n.x},${n.y})"><title>${n.id}: ${titles[n.type]}</title><rect x="-43" y="-29" width="86" height="58" rx="8" fill="${fill}" stroke="${!mini&&n.id===stationId?'#f0c777':'#a2ad8c'}" stroke-width="${!mini&&n.id===stationId?4:2}"/>${[-27,-9,9,27].map(x=>`<path d="M${x},-21v42" stroke="#a3ad8f" stroke-width="3" opacity=".4"/>`).join('')}<text x="0" y="-40" fill="#ece3ce" font-size="15" text-anchor="middle">${n.id} · ${n.type.toUpperCase()}</text>${mini?'':`<text y="51" fill="#c2c9ac" text-anchor="middle" font-size="13">S ${b?1:0} · Q ${active?1:0}</text>`}</g>`;}
 if(s)for(const n of l.nodes){const st=s.stations[n.id],b=st.box;if(!b)continue;const next=nodes[b.route[b.pos+1]],duration=.8;const canMove=next&&!s.stations[next.id].box;const p=canMove?Math.max(0,Math.min(.92,(st.elapsed/duration-.4)/.6)):0;const x=n.x+(next?next.x-n.x:0)*p,y=n.y+(next?next.y-n.y:0)*p;
 out+=`<g transform="translate(${x},${y})" pointer-events="none"><rect x="-16" y="-16" width="32" height="32" rx="3" fill="#e0b97d" stroke="#202b24" stroke-width="2"/><text y="5" text-anchor="middle" fill="#263027" font-weight="700">${b.id}</text></g>`;}
 return out;
}
function dimensions(l){return `0 0 ${Math.max(...l.nodes.map(n=>n.x))+70} ${Math.max(...l.nodes.map(n=>n.y))+75}`;}
function cards(){$('collection').innerHTML=L.layouts.map((l,i)=>`<button class="card" data-layout="${i}"><span class="number">${String(i+1).padStart(2,'0')}</span><span class="eyebrow">${l.level}${completed.includes(i)?' · COMPLETED':''}</span><h2>${l.name}</h2><svg viewBox="${dimensions(l)}" aria-hidden="true">${diagram(l,null,true)}</svg><p>${l.topic}</p></button>`).join('');}
function pause(){clearInterval(clock);clock=null;if(state){state.run=false;const commands=LayoutPLC.scan(layout,state,FloorEditor.rows(),plc,0);L.tick(layout,state,0,false,commands);render();}}
function resetPlant(){clearInterval(clock);clock=null;state=L.fresh(layout);plc=LayoutPLC.fresh();L.feed(layout,state);passed=false;$('check').textContent='Test my logic';delete $('check').dataset.pass;editor();render();}
function open(i){pause();selected=i;layout=L.layouts[i];state=L.fresh(layout);stationId=layout.nodes[0].id;plc=LayoutPLC.fresh();passed=false;$('auto').checked=true;$('check').textContent='Test my logic';delete $('check').dataset.pass;$('feedback').textContent='Start with an empty PLC program. Add rungs, then test your logic.';$('collection').hidden=true;document.querySelector('.intro').hidden=true;$('workspace').hidden=false;$('name').textContent=layout.name;$('difficulty').textContent=`FLOOR ${i+1} / 10 · ${layout.level}`;$('topic').textContent=layout.topic;$('station').innerHTML=layout.nodes.map(n=>`<option value="${n.id}">${n.id} · ${titles[n.type]}</option>`).join('');FloorEditor.open(layout,i,()=>{resetPlant();invalid();});L.feed(layout,state);editor();render();$('workspace').scrollIntoView({behavior:'smooth',block:'start'});}
function editor(){const st=state.stations[stationId],n=layout.nodes.find(n=>n.id===stationId);$('station').value=stationId;$('stationType').textContent=titles[n.type];$('fault').checked=st.fault;$('ready').checked=state.ready;}
function render(){$('diagram').setAttribute('viewBox',dimensions(layout));$('diagram').innerHTML=diagram(layout,state);$('stats').textContent=`Fed ${state.fed}  ·  Delivered ${state.delivered} / 6  ·  On line ${state.fed-state.delivered}  ·  Time ${state.time.toFixed(1)} s`;$('run').textContent=clock?'Pause system':'Run system';const st=state.stations[stationId];$('stationStatus').textContent=`${st.box?'Box '+st.box.id:'Empty'} · ${st.fault?'Fault active':st.output?'Output ON':'Output OFF'} · Elapsed ${st.elapsed.toFixed(1)} s · Lift position ${Math.round(st.position*100)}%`;FloorEditor.live(plc);}
function advance(){const commands=LayoutPLC.scan(layout,state,FloorEditor.rows(),plc);L.tick(layout,state,.1,$('auto').checked,commands);render();}
function run(){if(clock){pause();return;}state.run=true;clock=setInterval(advance,100/Number($('speed').value));render();}
function invalid(){passed=false;$('check').textContent='Test my logic';delete $('check').dataset.pass;$('feedback').textContent='Controls changed. Check commissioning again when ready.';}
$('collection').onclick=e=>{const b=e.target.closest('[data-layout]');if(b)open(Number(b.dataset.layout));};$('back').onclick=()=>{pause();$('workspace').hidden=true;$('collection').hidden=false;document.querySelector('.intro').hidden=false;cards();};
$('run').onclick=run;$('speed').onchange=()=>{if(clock){clearInterval(clock);clock=setInterval(advance,100/Number($('speed').value));}};
$('step').onclick=()=>{pause();state.run=true;advance();state.run=false;L.tick(layout,state,0,false);render();};
$('feed').onclick=()=>{if(!L.feed(layout,state))$('feedback').textContent='Entry occupied or circulation capacity reached. Let a box clear first.';render();};
$('reset').onclick=()=>{resetPlant();$('feedback').textContent='Simulation reset. Your program is unchanged.';};$('station').onchange=()=>{stationId=$('station').value;editor();render();};
function select(e){const g=e.target.closest('[data-id]');if(g){stationId=g.dataset.id;editor();render();}}
$('diagram').onclick=select;$('diagram').onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();select(e);}};
for(const id of ['fault','ready'])$(id).onchange=()=>{if(id==='ready')state.ready=$('ready').checked;else state.stations[stationId].fault=$('fault').checked;invalid();render();};
$('check').onclick=()=>{if(passed){open((selected+1)%L.layouts.length);return;}pause();const result=LayoutPLC.check(layout,FloorEditor.rows());passed=result.ok;$('check').dataset.pass=String(passed);$('check').textContent=passed?(selected===9?'Correct · Back to floor 1':'Correct · Next layout'):'Try again';$('feedback').textContent=result.message;if(passed&&!completed.includes(selected)){completed.push(selected);try{localStorage.setItem('plcquest.layouts.plc.done.v1',JSON.stringify(completed));}catch{$('feedback').textContent+=' Completion could not be saved in this browser.';}}};
document.addEventListener('visibilitychange',()=>{if(document.hidden)pause();});cards();
})();
